import{_t as e,it as t,n,rt as r}from"./chunks/framework.CzJE1L4g.js";var i=JSON.parse(`{"title":"For Agents","description":"","frontmatter":{},"headers":[],"relativePath":"ai/agents.md","filePath":"ai/agents.md","lastUpdated":1792596564000}`),a={name:`ai/agents.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="for-agents" tabindex="-1">For Agents <a class="header-anchor" href="#for-agents" aria-label="Permalink to “For Agents”">​</a></h1><p>给 Claude Code、Cursor、Codex、GitHub Copilot 这类 AI 编程工具的入口：在项目里用报表设计器与查看器时，怎样让 AI 写对接法；参与报表仓库开发时，AI 该读什么。</p><p>报表设计器没有单独的命令行或 MCP 服务端，AI 工具要的资料在两处：本站构建时产出的<a href="./llms">机读文档</a>，以及仓库根的 <code>AGENTS.md</code>。报表用到的 XiHan.UI 另有自己的 <a href="https://ui.docs.xihanfun.com/ai/agents" target="_blank" rel="noreferrer">AI 辅助开发</a>资料。</p><h2 id="复制这段提示词" tabindex="-1">复制这段提示词 <a class="header-anchor" href="#复制这段提示词" aria-label="Permalink to “复制这段提示词”">​</a></h2><p>把下面这段放进对话，或写进项目的 <code>AGENTS.md</code> / <code>CLAUDE.md</code> / <code>.cursor/rules</code>：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>这个项目用曦寒报表设计器（@xihan-report/*）设计报表、在业务页面显示报表。</span></span>
<span class="line"><span>写代码前先读 https://report.docs.xihanfun.com/llms.txt，按需读取其中列出的页面（站点地址后加 .md 取 Markdown）。</span></span>
<span class="line"><span>元素、属性、事件、报表定义的结构与问题码以文档和项目里装的版本为准，不要凭记忆写，也不要套用别的报表组件的 API。</span></span>
<span class="line"><span>用到 XiHan.UI 的组件、设计令牌、表达式引擎或语言包时，再读 https://ui.docs.xihanfun.com/llms.txt。</span></span></code></pre></div><h2 id="要装的包" tabindex="-1">要装的包 <a class="header-anchor" href="#要装的包" aria-label="Permalink to “要装的包”">​</a></h2><table tabindex="0"><thead><tr><th>用途</th><th>安装</th><th>注册</th><th>引入的样式</th></tr></thead><tbody><tr><td>业务页面显示报表</td><td><code>pnpm add @xihan-report/core @xihan-report/runtime @xihan-ui/styles</code></td><td><code>defineReportViewer()</code></td><td><code>@xihan-ui/styles/index.css</code>、<code>@xihan-report/runtime/style.css</code></td></tr><tr><td>设计报表</td><td><code>pnpm add @xihan-report/core @xihan-report/designer @xihan-report/runtime @xihan-ui/styles @xihan-ui/designer-shell</code></td><td><code>defineReportDesigner()</code></td><td>上面两份，再加 <code>@xihan-ui/designer-shell/style.css</code>、<code>@xihan-report/designer/style.css</code></td></tr><tr><td>计算字段与公式度量</td><td>另装 <code>@xihan-ui/expression</code></td><td>把 <code>createExpressionEngine()</code> 交给 <code>expressionEngine</code></td><td>—</td></tr><tr><td>界面语言</td><td>另装 <code>@xihan-ui/web-components</code></td><td>见下文「关键约定」</td><td>—</td></tr></tbody></table><p><code>@xihan-report/core</code> 用来在代码里写报表定义；报表定义直接写成 JSON 或从接口取回时，业务页面只要 <code>@xihan-report/runtime</code>。<code>@xihan-ui/*</code> 是报表各包的 peer 依赖，由项目装唯一的一份，与项目自己用的 XiHan.UI 同一个版本，页面上不会出现两份 UI。</p><h2 id="关键约定" tabindex="-1">关键约定 <a class="header-anchor" href="#关键约定" aria-label="Permalink to “关键约定”">​</a></h2><p>把这几条一并告诉 AI，常见的错写多出在这里：</p><ul><li><strong>先注册再用</strong>：元素不在 import 时注册，应用启动时调用一次 <code>defineReportViewer()</code> 或 <code>defineReportDesigner()</code>，重复调用不报错。</li><li><strong>对象走属性</strong>：报表定义、取数回调、参数取值与扩展这类对象交给元素的属性（<code>schema</code>、<code>dataProvider</code>、<code>parameters</code>、<code>extensions</code>），不写成 attribute。Vue 里用 <code>.prop</code> 修饰，并把 <code>xh-</code> 开头的标签声明为自定义元素，见<a href="./../guide/host#在框架里使用">在框架里使用</a>。</li><li><strong>报表定义是纯 JSON</strong>：不含函数与脚本；数据集只描述字段、不含数据，计算字段与公式度量是受限表达式，要给 <code>expressionEngine</code> 才能计算与校验。结构见<a href="./../guide/structure">报表结构</a>与<a href="./../reference/schema">报表定义类型</a>，问题码见<a href="./../reference/issues">问题码</a>。</li><li><strong>数据由宿主交回</strong>：组件不发网络请求。查看器与设计器按报表定义算出取数请求交给 <code>dataProvider</code>，宿主交回明细行（<code>kind: &#39;rows&#39;</code>）或按请求聚合好的行（<code>kind: &#39;aggregated&#39;</code>），见<a href="./../guide/host">与宿主集成</a>。</li><li><strong>宿主管保存</strong>：设计器每次修改派发 <code>schema-change</code>，保存命令（Ctrl / ⌘ + S 或「文件」菜单的「保存」）派发 <code>save</code>，宿主存好后调用 <code>markSaved()</code>，见<a href="./../guide/designer#打开与保存">打开与保存</a>。</li><li><strong>扩展走 <code>extensions</code></strong>：卡片与视图种类、渲染、导出器、取数中间件、属性编辑器、命令、面板与物料都经 <code>extensions</code> 登记，按实例传入，不改包内源码，见<a href="./../guide/extensions">扩展</a>。</li><li><strong>语言包合并后全局设置</strong>：界面文字缺省是英文。语言包的名字是 <code>report</code> 加 XiHan.UI 语言包的名字（<code>zhCN</code> 对 <code>reportZhCN</code>），与 UI 同一语言的那份合并：<code>setXhConfig(mergeXhConfig(zhCN, reportZhCN))</code>，见<a href="./../quickstart#界面语言">快速开始</a>。</li></ul><h2 id="参与报表仓库开发" tabindex="-1">参与报表仓库开发 <a class="header-anchor" href="#参与报表仓库开发" aria-label="Permalink to “参与报表仓库开发”">​</a></h2><p>仓库根的 <code>AGENTS.md</code> 是写给 AI 的仓库规范：</p><table tabindex="0"><thead><tr><th>内容</th><th>说明</th></tr></thead><tbody><tr><td>仓库概览与目录结构</td><td><code>report/</code> 是三个包与开发预览页的工作区，<code>docs/</code> 是本站</td></tr><tr><td>常用命令</td><td>构建、类型检查、单测、Lint、产物契约与冒烟，以及文档站的命令</td></tr><tr><td>分层与依赖</td><td><code>designer → runtime → core</code>，core 不碰 DOM，运行时依赖只允许 <code>@xihan-report/*</code> 与 <code>@xihan-ui/*</code></td></tr><tr><td>硬性约定</td><td>模板即数据、无全局状态、数据由使用方提供、对外契约、命名与语言包、样式、注释</td></tr><tr><td>文档站、发版、Git 与提交</td><td>各自的做法与禁止事项</td></tr></tbody></table><p><code>CLAUDE.md</code> 是指向 <code>AGENTS.md</code> 的链接，Claude Code 打开仓库即读到；Codex 直接读 <code>AGENTS.md</code>；Cursor、GitHub Copilot 等工具在各自的规则文件里写一句「先读仓库根的 AGENTS.md」即可。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to “相关”">​</a></h2><ul><li><a href="./llms">LLMs.txt</a> · <a href="./../quickstart">快速开始</a> · <a href="./../guide/host">与宿主集成</a></li><li><a href="https://ui.docs.xihanfun.com/ai/agents" target="_blank" rel="noreferrer">XiHan.UI 的 AI 辅助开发</a></li></ul>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};